    GameObject layerObject = new GameObject("UiFrontLayer", typeof(RectTransform));
    layerObject.transform.SetParent(canvasRoot, false);

    layerRect = layerObject.GetComponent<RectTransform>();
    layerRect.anchorMin = Vector2.zero;
