private static Transform FindExistingLayer(Transform canvasRoot)
{
    if (canvasRoot == null)
        return null;

    Transform named = canvasRoot.Find("UiFrontLayer");
    if (named != null)
        return named;

    for (int i = 0; i < canvasRoot.childCount; i++)
    {
        Transform child = canvasRoot.GetChild(i);
        if (child != null && child.name == "UiFrontLayer")
            return child;
    }

    return null;
}

private static void EnsureLayerComponents(RectTransform layer)
{
    if (layer == null)
        return;

    Canvas canvas = layer.GetComponent<Canvas>();
    if (canvas == null)
        canvas = layer.gameObject.AddComponent<Canvas>();
    canvas.overrideSorting = true;
    canvas.sortingOrder = 500;

    if (layer.GetComponent<GraphicRaycaster>() == null)
        layer.gameObject.AddComponent<GraphicRaycaster>();
}

