private static Color ReadRendererEmission(Renderer renderer, out bool hasEmissionProperty)
{
    hasEmissionProperty = false;
    if (renderer == null)
        return Color.black;

    Material mat = renderer.sharedMaterial;
    if (mat == null)
        return Color.black;

    // HDRP Lit uses _EmissiveColor (or emissive map × tint). Legacy _EmissionColor is misleading.
    if (IsHdrpShader(mat.shader) && mat.HasProperty(EmissiveColorId))
    {
        hasEmissionProperty = true;
        Color emission = mat.GetColor(EmissiveColorId);
        if (mat.HasProperty(UseEmissiveIntensityId)
            && mat.GetFloat(UseEmissiveIntensityId) > 0.5f
            && mat.HasProperty("_EmissiveIntensity"))
        {
            emission *= mat.GetFloat("_EmissiveIntensity");
        }

        return emission;
    }

    if (mat.HasProperty(EmissionColorId))
    {
        hasEmissionProperty = true;
        return mat.GetColor(EmissionColorId);
    }

    if (mat.HasProperty(EmissiveColorId))
    {
        hasEmissionProperty = true;
        return mat.GetColor(EmissiveColorId);
    }

    return Color.black;
}

private static bool RendererSupportsEmissiveGlow(Renderer renderer)
{
    Material mat = renderer != null ? renderer.sharedMaterial : null;
    if (mat == null)
        return false;

    if (mat.HasProperty(EmissiveColorId) || mat.HasProperty(EmissionColorId))
        return true;

    return mat.IsKeywordEnabled(HdrpEmissiveColorMapKeyword)
           || mat.IsKeywordEnabled(HdrpEmissiveColorKeyword)
           || mat.IsKeywordEnabled(UrpEmissionKeyword);
}

private static bool IsHdrpShader(Shader shader)
{
    if (shader == null)
        return false;

    string name = shader.name;
    return name.StartsWith("HDRP/", StringComparison.Ordinal)
           || name.StartsWith("Hidden/HDRP", StringComparison.Ordinal);
}

