private static Color ReadRendererEmission(Renderer renderer, out bool hasEmissionProperty)
{
    hasEmissionProperty = false;
    if (renderer == null)
        return Color.black;

    Material mat = renderer.sharedMaterial;
    if (mat == null)
        return Color.black;

    // HDRP Lit uses _EmissiveColor (or emissive map × tint). Legacy _EmissionColor is misleading.
    if (IsHdrpShader(mat.shader) && mat.HasProperty(EmissiveColorId))
    {
        hasEmissionProperty = true;
        Color emission = mat.GetColor(EmissiveColorId);
        if (mat.HasProperty(UseEmissiveIntensityId)
            && mat.GetFloat(UseEmissiveIntensityId) > 0.5f
            && mat.HasProperty("_EmissiveIntensity"))
        {
            emission *= mat.GetFloat("_EmissiveIntensity");
        }

        return emission;
    }

    if (mat.HasProperty(EmissionColorId))
    {
        hasEmissionProperty = true;
        return mat.GetColor(EmissionColorId);
    }

    if (mat.HasProperty(EmissiveColorId))
    {
        hasEmissionProperty = true;
        return mat.GetColor(EmissiveColorId);
    }

    return Color.black;
}

private static bool RendererSupportsEmissiveGlow(Renderer renderer)
{
    Material mat = renderer != null ? renderer.sharedMaterial : null;
    if (mat == null)
        return false;

    if (mat.HasProperty(EmissiveColorId) || mat.HasProperty(EmissionColorId))
        return true;

    return mat.IsKeywordEnabled(HdrpEmissiveColorMapKeyword)
           || mat.IsKeywordEnabled(HdrpEmissiveColorKeyword)
           || mat.IsKeywordEnabled(UrpEmissionKeyword);
}

private static bool IsHdrpShader(Shader shader)
{
    if (shader == null)
        return false;

    string name = shader.name;
    return name.StartsWith("HDRP/", StringComparison.Ordinal)
           || name.StartsWith("Hidden/HDRP", StringComparison.Ordinal);
}

private void ApplyHeatTint(ItemData tool, float heat01)
{
    EnsureHeatRenderers(tool);
    if (heatRenderers == null || heatRenderers.Length == 0)
        return;

    heatPropertyBlock ??= new MaterialPropertyBlock();
    heat01 = Mathf.Clamp01(heat01);

    for (int i = 0; i < heatRenderers.Length; i++)
    {
        Renderer renderer = heatRenderers[i];
        if (renderer == null)
            continue;

        Color baseColor = i < heatBaseColors.Length ? heatBaseColors[i] : Color.white;
        Color baseEmission = i < heatBaseEmissions.Length ? heatBaseEmissions[i] : Color.black;
        bool supportsEmission = i < heatHadEmission.Length && heatHadEmission[i];
        Color emissionRest = supportsEmission ? baseEmission : Color.black;
        Color glow = OverheatEmission * (OverheatEmissionIntensity * OverheatVisualIntensityMultiplier);
        Color emission = Color.Lerp(emissionRest, glow, heat01);

        int materialCount = renderer.sharedMaterials != null && renderer.sharedMaterials.Length > 0
            ? renderer.sharedMaterials.Length
            : 1;
        for (int materialIndex = 0; materialIndex < materialCount; materialIndex++)
        {
            renderer.GetPropertyBlock(heatPropertyBlock, materialIndex);
            heatPropertyBlock.SetColor(BaseColorId, baseColor);
            heatPropertyBlock.SetColor(ColorId, baseColor);
            if (supportsEmission)
            {
                heatPropertyBlock.SetColor(EmissiveColorId, emission);
                heatPropertyBlock.SetColor(EmissionColorId, emission);
            }

            renderer.SetPropertyBlock(heatPropertyBlock, materialIndex);
        }
    }

    // MPB cannot toggle shader keywords — enable the emissive path on material instances once.
    if (heat01 > 0.01f && !heatEmissionKeywordsEnabled)
    {
        for (int i = 0; i < heatRenderers.Length; i++)
            EnsureRendererEmissionEnabled(heatRenderers[i]);
        heatEmissionKeywordsEnabled = true;
    }
}

private static void EnsureRendererEmissionEnabled(Renderer renderer)
{
    if (renderer == null)
        return;

    // Touching .materials instantiates unique mats so emission keywords can be enabled without
    // mutating shared assets. Instances are cleaned up with the weapon GameObject.
    Material[] mats = renderer.materials;
    if (mats == null)
        return;

    for (int i = 0; i < mats.Length; i++)
        EnableEmissionOnMaterial(mats[i]);
}

private static void EnableEmissionOnMaterial(Material mat)
{
    if (mat == null)
        return;

    if (IsHdrpShader(mat.shader))
    {
        // Mining tool mesh uses HDRP Lit + _EMISSIVE_COLOR_MAP. MPB tints via _EmissiveColor.
        if (mat.HasProperty(UseEmissiveIntensityId) && mat.GetFloat(UseEmissiveIntensityId) > 0.5f)
        {
            mat.SetFloat(UseEmissiveIntensityId, 0f);
            if (mat.HasProperty(EmissiveColorId))
                mat.SetColor(EmissiveColorId, Color.black);
        }

        if (mat.IsKeywordEnabled(HdrpEmissiveColorMapKeyword))
            return;

        if (!mat.IsKeywordEnabled(HdrpEmissiveColorKeyword))
            mat.EnableKeyword(HdrpEmissiveColorKeyword);
        return;
    }

    if (!mat.HasProperty(EmissionColorId) && !mat.HasProperty(EmissiveColorId))
        return;

    if (!mat.IsKeywordEnabled(UrpEmissionKeyword))
        mat.EnableKeyword(UrpEmissionKeyword);
}

private void RestoreHeatTint()
{
    if (heatRenderers == null)
        return;

    heatPropertyBlock ??= new MaterialPropertyBlock();
    for (int i = 0; i < heatRenderers.Length; i++)
    {
        Renderer renderer = heatRenderers[i];
        if (renderer == null)
            continue;

        int materialCount = renderer.sharedMaterials != null && renderer.sharedMaterials.Length > 0
            ? renderer.sharedMaterials.Length
            : 1;
        for (int materialIndex = 0; materialIndex < materialCount; materialIndex++)
            renderer.SetPropertyBlock(null, materialIndex);
    }

    heatVisualRoot = null;
    heatRenderers = null;
    heatBaseColors = null;
    heatBaseEmissions = null;
    heatHadEmission = null;
    heatEmissionKeywordsEnabled = false;
}

